import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './Product.css';
import PageTitle from '../PageTitle';
import { useDispatch } from 'react-redux';
import { addToCart } from '../redux/actions'; // Redux action import ediliyor

function Product() {
  const [isModalOpen, setModalOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [products, setProducts] = useState([]); // Ürünler için state
  const [filteredProducts, setFilteredProducts] = useState([]); // Filtrelenmiş ürünler için state
  const [loading, setLoading] = useState(true); // Yükleme durumu
  const [error, setError] = useState(null); // Hata durumu

  const dispatch = useDispatch(); // Redux dispatch kullanımı

  // Ürünleri API'den alıyoruz
  useEffect(() => {
    axios.get('http://localhost:3001/api/products') // API URL'ini doğru girdiğinizden emin olun
      .then(response => {
        setProducts(response.data); // Gelen veriyi state'e ekle
        setFilteredProducts(response.data); // Filtrelenmiş ürünler başta tüm ürünlerle eşitleniyor
        setLoading(false); // Yükleme bitti
      })
      .catch(error => {
        console.error('Ürünler alınırken hata oluştu:', error);
        setError('Ürünler alınırken bir hata oluştu. Lütfen tekrar deneyin.');
        setLoading(false);
      });
  }, []); // İlk renderda çalışır

  // Modal açma
  const openModal = (product) => {
    setSelectedProduct(product);
    setModalOpen(true);
  };

  // Modal kapama
  const closeModal = () => {
    setModalOpen(false);
    setSelectedProduct(null);
  };

  // Ürünleri kategoriye göre filtreleme
  const filterByCategory = (category) => {
    if (category === 'all') {
      setFilteredProducts(products); // 'all' seçildiğinde tüm ürünleri göster
    } else {
      const filtered = products.filter(product => product.category === category);
      setFilteredProducts(filtered);
    }
  };

  // Sepete ürün ekleme işlemi
  const addToCartHandler = (product) => {
    dispatch(addToCart(product)); // Redux action çağrısı ile sepete ürün ekleme
    alert(`${product.name} sepete eklendi!`);
  };

  return (
    <>
      <PageTitle title="Ürünümüz" />
      <div>
        <div className="baslik">Ürünümüz Hakkında</div>
        <div className="aboutcard">
          <div className="about-page">
            <h1 id="about-title">BeeonHive</h1>
            <p>
              BeeonHive ile birlikte kovanlarınızı web uygulamamız üzerinden kolayca takip edebilirsiniz. 2'si ana modül olmak üzere toplam
              6 modül ile birlikte kovanınızın sıcaklık ve nemini, karbondioksit ve sülfür oranını ve hatta GPS modülü ile konumunu öğrenebilirsiniz.
              Müdahale edilmesi gereken durumlarda ise gerekli ilaçlamayı da yapabilirsiniz.
            </p>
          </div>
        </div>
      </div>

      {/* Kategori filtreleme butonları */}
      <div className="filter-buttons">
        <button onClick={() => filterByCategory('Ana Modül')}>Ana Modül</button>
        <button onClick={() => filterByCategory('Ek Modül')}>Ek Modül</button>
        <button onClick={() => filterByCategory('all')}>Tümü</button> {/* Tümünü göstermek için */}
      </div>

      {/* Ürünlerin listelendiği kısım */}
      <div className="product-container">
        {loading ? (
          <div className="loading-spinner">Yükleniyor...</div>
        ) : error ? (
          <p>{error}</p> // Hata mesajı göster
        ) : (
          filteredProducts.length > 0 ? (
            filteredProducts.map((product) => (
              <div className="product-box" key={product._id}>
                <img src={product.photo} alt={product.name} className="product-image" />
                <h3>{product.name}</h3>
                <p>{product.category}</p>
                <p>{product.price} TL</p>
                <button onClick={() => openModal(product)}>Detayları Göster</button>
                <button onClick={() => addToCartHandler(product)}>Sepete Ekle</button> {/* Sepete Ekle butonu */}
              </div>
            ))
          ) : (
            <p>Ürün bulunamadı.</p>
          )
        )}
      </div>

      {/* Modal */}
      {isModalOpen && (
        <div className="modal-overlay" onClick={closeModal}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <button className="modal-close" onClick={closeModal} aria-label="Modalı Kapat">×</button>
            <h2>{selectedProduct.name}</h2>
            <img src={selectedProduct.photo} alt={selectedProduct.name} className="product-image" />
            <p>{selectedProduct.productdetails}</p>
            <button className="close" onClick={closeModal}>Kapat</button>
          </div>
        </div>
      )}
    </>
  );
}

export default Product;
